import numpy as np, textwrap
code = r'''
import numpy as np
def arc(cx,cy,rx,ry,t0,t1,n=40):
    t=np.deg2rad(np.linspace(t0,t1,n)); return np.stack([cx+rx*np.cos(t),cy-ry*np.sin(t)],1)
def line(a,b,n=25):
    s=np.linspace(0,1,n)[:,None]; return np.array(a)*(1-s)+np.array(b)*s
def strokes(d,rng):
    j=lambda: rng.normal(0,0.03)
    if d==0: return arc(0.5,0.5,0.3+j(),0.42,0,360,80)
    if d==1:
        p=[line((0.5,0.08),(0.5,0.92))]
        if rng.random()<0.6: p.append(line((0.33,0.27),(0.5,0.08)))
        if rng.random()<0.3: p.append(line((0.35,0.92),(0.65,0.92)))
        return np.concatenate(p)
    if d==2: return np.concatenate([arc(0.5,0.33,0.26,0.25,160,-30),line((0.72,0.455),(0.22+j(),0.9)),line((0.22,0.9),(0.82,0.9+j()))])
    if d==3: return np.concatenate([arc(0.48,0.3,0.24,0.2,150,-90),arc(0.48,0.7,0.24,0.22,90,-150)])
    if d==4: return np.concatenate([line((0.58+j(),0.08),(0.18,0.65)),line((0.18,0.65),(0.85,0.65)),line((0.65,0.3),(0.65,0.95))])
    if d==5: return np.concatenate([line((0.78,0.08),(0.3,0.08)),line((0.3,0.08),(0.28,0.45)),arc(0.48,0.66,0.26,0.25,130,-150)])
    if d==6: return np.concatenate([line((0.7,0.08),(0.28+j(),0.62)),arc(0.5,0.68,0.23,0.23,0,360,60)])
    if d==7:
        p=[line((0.18,0.08),(0.82,0.08)),line((0.82,0.08),(0.42+j(),0.94))]
        if rng.random()<0.3: p.append(line((0.4,0.5),(0.75,0.5)))
        return np.concatenate(p)
    if d==8: return np.concatenate([arc(0.5,0.27,0.2,0.2,0,360,50),arc(0.5,0.71,0.24,0.23,0,360,60)])
    if d==9: return np.concatenate([arc(0.5,0.32,0.23,0.22,0,360,60),line((0.73,0.33),(0.62+j(),0.94))])
yy,xx=np.mgrid[0:32,0:32]; PIX=np.stack([xx.ravel()+0.5,yy.ravel()+0.5],1)
def make(n,seed=0,labels=None):
    rng=np.random.default_rng(seed)
    y=rng.integers(0,10,n) if labels is None else labels
    X=np.zeros((n,64))
    for i in range(n):
        P=strokes(y[i],rng)-0.5
        th=np.deg2rad(rng.normal(0,10)); sh=rng.normal(0,0.15)
        w=rng.uniform(0.6,1.0); h=rng.uniform(0.85,1.0)
        A=np.array([[np.cos(th),-np.sin(th)],[np.sin(th),np.cos(th)]])@np.array([[1,sh],[0,1]])@np.diag([w,h])
        P=P@A.T*29+16+rng.normal(0,1.0,2)
        P=P+rng.normal(0,0.4,P.shape)
        D=np.sqrt(((PIX[:,None,:]-P[None])**2).sum(-1)).min(1)
        t=rng.uniform(1.3,3.2)
        img=np.clip(t+0.5-D,0,1).reshape(32,32)
        X[i]=img.reshape(8,4,8,4).mean((1,3)).ravel()
    X=np.clip(X*rng.uniform(1.0,1.3,(n,1)),0,1)
    X=np.round(X*16)/16
    return X,y
def load(n):
    d=np.load(n+'.npz',allow_pickle=True); return {k:d[k] for k in d.files}
def act(m,z): return np.maximum(z,0) if str(m['act'])=='relu' else np.tanh(z)
def fwd(m,X):
    z1=X@m['W0']+m['b0']; h1=act(m,z1); h2=act(m,h1@m['W1']+m['b1']); return z1,h1,h2@m['W2']+m['b2']
def fromz(m,z1):
    h2=act(m,act(m,z1)@m['W1']+m['b1']); return h2@m['W2']+m['b2']
'''
open('gen.py','w').write(code)
from gen import *
A,B=load('A'),load('B')
X,y=make(6000,1); np.savez('syn.npz',X=X,y=y)
_,hA,lA=fwd(A,X); zB,_,lB=fwd(B,X)
pA,pB=lA.argmax(1),lB.argmax(1)
print('A acc',(pA==y).mean(),'B acc',(pB==y).mean(),'agree',(pA==pB).mean())
for k in range(10): print(k,(pA[y==k]==k).mean().round(2),(pB[y==k]==k).mean().round(2))
H=np.c_[hA,np.ones(len(hA))]; S=np.linalg.lstsq(H,zB,rcond=None)[0]
pb=fromz(B,H@S).argmax(1)
print('bridge vs y',(pb==y).mean(),'vs B',(pb==pB).mean())
for r in X[y==3][:1]: print((r.reshape(8,8)*9).round().astype(int))
